#!/bin/bash
# تشغيل كل الاختبارات على قاعدة محلية نظيفة
P="psql -h /var/lib/pgtest -p 5499 -U postgres -q -v ON_ERROR_STOP=1"
$P -c "drop schema if exists public cascade; create schema public; grant all on schema public to postgres, public; drop schema if exists auth cascade; drop schema if exists storage cascade; drop schema if exists extensions cascade; drop schema if exists t cascade; drop role if exists anon; drop role if exists authenticated;" 2>/dev/null
$P -f tests/00_supabase_stub.sql && $P -f supabase/01_schema.sql 2>/dev/null && $P -f supabase/02_storage.sql 2>/dev/null && $P -f supabase/03_seed_protocols.sql && $P -f supabase/05_hardening.sql && $P -f supabase/06_patients_view.sql && $P -f supabase/07_step5.sql && $P -f supabase/08_protocol_file.sql && $P -f supabase/09_dose_instructions.sql && $P -f supabase/10_drug_cycles.sql && $P -f supabase/12_remove_auc.sql && $P -f supabase/13_user_activation.sql && $P -f supabase/14_approval_chain.sql && $P -f supabase/15_lab_ocr.sql && $P -f supabase/16_admin_roles.sql && $P -f supabase/17_admin_delete_user.sql && $P -f supabase/18_lab_alert_link.sql && $P -f supabase/19_lab_alert_cycle_day.sql && $P -f supabase/20_lab_alert_day_before.sql && $P -f supabase/21_lock_prepared_doses.sql && $P -f supabase/22_activation_codes_hardening.sql && $P -f supabase/24_delete_user_identity_email.sql && $P -f supabase/25_internal_pharmacist_role.sql && $P -f supabase/26_internal_pharmacy.sql && $P -f supabase/32_disease_status.sql && $P -f supabase/33_report_reaction.sql && $P -f supabase/34_practicing_pharmacist.sql && $P -f supabase/35_plan_dose_edit_restore_protocol.sql && $P -f supabase/36_pending_specialists.sql && $P -f supabase/37_admin_delete_protocol.sql && $P -f supabase/38_chief_pharmacist_approvals.sql && $P -f supabase/39_chief_approvals_original_only.sql || exit 1
for f in tests/01_flow_test.sql tests/02_extra_test.sql tests/03_patients_test.sql tests/04_step5_test.sql tests/05_protocol_file_test.sql tests/06_drug_cycles_test.sql tests/07_activation_test.sql tests/08_approval_chain_test.sql tests/09_lab_ocr_test.sql tests/10_admin_roles_test.sql tests/11_admin_delete_test.sql tests/12_lab_alert_rule_test.sql tests/13_activation_hardening_test.sql tests/14_identity_email_test.sql tests/15_internal_pharmacy_test.sql tests/16_disease_status_test.sql; do
  psql -h /var/lib/pgtest -p 5499 -U postgres -f $f 2>&1 | grep -E '^(psql.*NOTICE:  )?[TEPSFCVLRDACI][0-9]+|ERROR|DONE|FAIL' | sed 's/^psql:[^ ]* NOTICE:  //'
done
bash tests/concurrency_activation.sh
